={{ JSON.stringify({
  model: 'claude-opus-5',
  max_tokens: 16000,
  system: 'You convert daily WhatsApp group messages from a property maintenance business into Job Register rows. Extract every job mentioned. For each job output: date (yyyy-MM-dd; the message may use d/M or words like today/tomorrow/yesterday - resolve them against the reference date given), unit (format PREFIX-Floor-Unit where the property prefix is PV=Park View, R=Rubica, OV=Ocean View, L=Luminari, e.g. PV-12-03 or R-5-11; normalize full property names like park view 12-3 to PV-12-3; empty string if not found), category (one of CLEANING, DEEP_CLEANING, PLUMBING, ELECTRICAL, AIRCON, GENERAL_REPAIR, UNKNOWN - correct obvious typos when classifying), description (short clean summary of the job), status (COMPLETED if the message says the work is done, NOT_COMPLETED if it says it could not be done, WAITING if waiting for parts/access, otherwise PENDING), needsReview (true when unit is empty or category is UNKNOWN or the message is ambiguous), reviewReason (short reason when needsReview is true, else empty string). Respond ONLY with a JSON array of these job objects - no markdown fences, no commentary. If the message contains no jobs, respond with [].',
  messages: [{
    role: 'user',
    content: 'Reference date (today): ' + new Date().toISOString().slice(0, 10) + '\n\nWhatsApp message:\n' + String($json.body.message || $json.body.text || '')
  }]
}) }}

parameters.jsCode:
// Turn Claude's response into Job Register rows.
const res = $json;
if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined this message; enter the job manually.');
}
const textBlock = (res.content || []).find((b) => b.type === 'text');
if (!textBlock) {
  throw new Error('No text in Claude response');
}
let text = textBlock.text.trim();
// Strip accidental markdown fences just in case
text = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Claude did not return valid JSON: ' + text.slice(0, 200));
}
if (!Array.isArray(parsed)) parsed = [parsed];

const today = new Date().toISOString().slice(0, 10);
const newId = () => 'J-' + Math.random().toString(36).slice(2, 10).toUpperCase();
const CATS = ['CLEANING', 'DEEP_CLEANING', 'PLUMBING', 'ELECTRICAL', 'AIRCON', 'GENERAL_REPAIR', 'UNKNOWN'];
const STATUSES = ['PENDING', 'WAITING', 'COMPLETED', 'NOT_COMPLETED'];
const raw = String($('Intake webhook').first().json.body.message || $('Intake webhook').first().json.body.text || '');
const sender = String($('Intake webhook').first().json.body.sender || 'WhatsApp');

return parsed.map((j) => {
  const unit = String(j.unit || '').toUpperCase();
  const category = CATS.includes(j.category) ? j.category : 'UNKNOWN';
  const status = STATUSES.includes(j.status) ? j.status : 'PENDING';
  const reasons = [];
  if (!unit) reasons.push('Unit number not found');
  if (category === 'UNKNOWN') reasons.push('Category could not be classified');
  if (j.needsReview && j.reviewReason) reasons.push(String(j.reviewReason));
  const needsReview = reasons.length > 0;
  return { json: {
    id: newId(),
    date: /^\d{4}-\d{2}-\d{2}$/.test(String(j.date)) ? j.date : today,
    unit,
    category,
    description: String(j.description || '').slice(0, 160),
    status,
    needsReview: needsReview ? 'TRUE' : 'FALSE',
    reviewReason: [...new Set(reasons)].join('; '),
    remarks: '',
    customerCharge: '',
    contractorPayable: '',
    invoiced: 'FALSE',
    paid: 'FALSE',
    createdBy: sender,
    rawMessage: raw
  } };
});

const rows = $input.all().map((i) => i.json);
return [{ json: {
  ok: true,
  added: rows.length,
  flaggedForReview: rows.filter((r) => String(r.needsReview) === 'TRUE').length,
  jobs: rows.map((r) => ({ id: r.id, unit: r.unit, category: r.category, status: r.status }))
} }];
